class Shape {
public: enum Kind { CIRCLE, SQUARE } kind;
};
double area(const Shape& s) {
  switch (s.kind) {
    case Shape::CIRCLE: return 3.14 * s.r * s.r;
    case Shape::SQUARE: return s.side * s.side;
  }
  return 0.0;
}
double perimeter(const Shape& s) {
  switch (s.kind) { /* same shape over again */ return 0.0; }
}
